CREATE TABLE IF NOT EXISTS notes(id TEXT PRIMARY KEY,space TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,parent TEXT,archived INTEGER NOT NULL,props TEXT NOT NULL,data BLOB NOT NULL,rev INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS notes_tree ON notes(space,kind,archived,parent);
CREATE VIRTUAL TABLE IF NOT EXISTS words USING fts5(id UNINDEXED,space UNINDEXED,title,body,tokenize='unicode61');
CREATE TABLE IF NOT EXISTS backlinks(source TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,target TEXT NOT NULL,PRIMARY KEY(source,target));
CREATE INDEX IF NOT EXISTS backlinks_target ON backlinks(target);
CREATE TABLE IF NOT EXISTS versions(id TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,rev INTEGER NOT NULL,time INTEGER NOT NULL,record BLOB NOT NULL,label TEXT,cause TEXT,PRIMARY KEY(id,rev));
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY REFERENCES notes(id) ON DELETE CASCADE,rev INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS private_state(id TEXT PRIMARY KEY,value BLOB NOT NULL);
PRAGMA user_version=7;
CREATE TABLE IF NOT EXISTS deletions(space TEXT NOT NULL,id TEXT PRIMARY KEY,confirmed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS file_owners(id TEXT PRIMARY KEY,doc TEXT NOT NULL,space TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS files_by_doc ON file_owners(doc);
CREATE TABLE IF NOT EXISTS erased_files(id TEXT PRIMARY KEY,space TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS page_files(doc TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,file TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',retry_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(doc,file));
CREATE INDEX IF NOT EXISTS pending_files ON page_files(retry_at) WHERE status='pending';
CREATE TABLE IF NOT EXISTS page_artwork(space TEXT NOT NULL,doc TEXT NOT NULL,file TEXT NOT NULL,PRIMARY KEY(space,doc,file));
CREATE VIRTUAL TABLE IF NOT EXISTS file_words USING fts5(name,body,tokenize='unicode61');
CREATE TABLE IF NOT EXISTS erased_file_docs(file TEXT PRIMARY KEY,doc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS listing(shard TEXT NOT NULL,id TEXT NOT NULL,space TEXT NOT NULL,parent TEXT,archived INTEGER,stamp INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(shard,id));
CREATE INDEX IF NOT EXISTS listing_by_id ON listing(id);
CREATE TABLE IF NOT EXISTS discards(id TEXT PRIMARY KEY,space TEXT NOT NULL,owner TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS row_marks(id TEXT PRIMARY KEY,parent TEXT NOT NULL,mark INTEGER NOT NULL,gone INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS row_marks_recent ON row_marks(parent,mark);
CREATE INDEX IF NOT EXISTS row_marks_latest ON row_marks(mark);
CREATE TABLE IF NOT EXISTS row_clock(id INTEGER PRIMARY KEY CHECK(id=1),mark INTEGER NOT NULL);
INSERT OR IGNORE INTO row_clock VALUES(1,(SELECT COALESCE(MAX(mark),0) FROM row_marks));
CREATE TABLE IF NOT EXISTS save_times(id TEXT PRIMARY KEY REFERENCES notes(id) ON DELETE CASCADE,time INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS version_files(file TEXT PRIMARY KEY,doc TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,rev INTEGER,state INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS version_files_by_doc ON version_files(doc);
CREATE TABLE IF NOT EXISTS erased_texts(doc TEXT NOT NULL,file TEXT NOT NULL,space TEXT NOT NULL,owner TEXT NOT NULL,PRIMARY KEY(doc,file));
CREATE TABLE IF NOT EXISTS sent_files(id TEXT PRIMARY KEY,doc TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS sent_files_by_doc ON sent_files(doc);
